  Lemma stack0_ok_errno : stack0_ok (AERRNO, AERRNO + 4).
  Proof. right. cbn [fst snd]. pose proof aceil_facts as (AF & _). unfold AERRNO, ATP, sh, ASHADOW_BASE. Z.div_mod_to_equations. lia. Qed.

  Lemma win_fr_errno : forall ff k, win_fr ff k (AERRNO, AERRNO + 4).
  Proof. intros ff k. left. cbn [fst snd]. unfold AERRNO, ATP, ALOWSH_LO. lia. Qed.

  Lemma awin_errno : awin (AERRNO, AERRNO + 4).
  Proof. split; [apply aconst_ok_errno| split; [apply stack0_ok_errno| left; cbn [fst snd]; unfold AERRNO, ATP, ALOWSH_LO; lia]]. Qed.

